import{_ as e,o as d,c as r,a2 as a}from"./chunks/framework.CvydjLy7.js";const p=JSON.parse('{"title":"课程导读","description":"","frontmatter":{"title":"课程导读"},"headers":[{"level":2,"title":"官方文档缺什么","slug":"官方文档缺什么","link":"#官方文档缺什么","children":[]},{"level":2,"title":"官方章节与本教程的对应","slug":"官方章节与本教程的对应","link":"#官方章节与本教程的对应","children":[]},{"level":2,"title":"适合谁读","slug":"适合谁读","link":"#适合谁读","children":[]},{"level":2,"title":"怎么用这个站点","slug":"怎么用这个站点","link":"#怎么用这个站点","children":[]},{"level":2,"title":"关于版本","slug":"关于版本","link":"#关于版本","children":[]}],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1789497795000}'),o={name:"guide/index.md"};function n(i,t,l,s,h,c){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="课程导读" tabindex="-1">课程导读 <a class="header-anchor" href="#课程导读" aria-label="Permalink to &quot;课程导读&quot;">​</a></h1><p>这套教程按 Spring Boot 官方文档 4.1.x 的章节顺序重写，终点是一个前后端分离的全端项目：Spring Boot 4 后端 + Vue 3 管理端。正文里的代码全部来自本机实际编译、启动、验证过的工程，不是从文档里摘的片段。</p><p>版本基线：Spring Boot <strong>4.1.1</strong> · Spring Framework <strong>7.0.9</strong> · Java <strong>21 LTS</strong> · Maven <strong>3.9.11</strong>。</p><h2 id="官方文档缺什么" tabindex="-1">官方文档缺什么 <a class="header-anchor" href="#官方文档缺什么" aria-label="Permalink to &quot;官方文档缺什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>官方文档的形态</th><th>学习时的实际困难</th></tr></thead><tbody><tr><td>按特性逐条罗列，一个特性一小节</td><td>读完之后，不知道这些特性在一个项目里怎么拼起来</td></tr><tr><td>代码片段多为最小示例</td><td>片段散落在各章，缺少&quot;同一个项目从零长起来&quot;的连续感</td></tr><tr><td>API 文档六万余页</td><td>能查到类名和方法签名，但判断不出什么时候该用哪一个</td></tr><tr><td>版本变更写在发布说明里</td><td>3.x 的写法在 4.x 会直接报错，网上的教程大半已经过时</td></tr></tbody></table><p>这份教程的做法是保留官方的组织顺序，在每一节后面补上同一个项目里的实现，并把实测结果（启动耗时、jar 体积、镜像层大小、内存占用、测试耗时）写进正文。遇到拿不准的地方，可以顺着每篇开头的官方章节链接回原文核对。</p><h2 id="官方章节与本教程的对应" tabindex="-1">官方章节与本教程的对应 <a class="header-anchor" href="#官方章节与本教程的对应" aria-label="Permalink to &quot;官方章节与本教程的对应&quot;">​</a></h2><table tabindex="0"><thead><tr><th>官方章节</th><th>页面数</th><th>本教程对应</th></tr></thead><tbody><tr><td>Getting Started / Tutorial</td><td>3</td><td>第 1 篇</td></tr><tr><td>Reference → Using Spring Boot</td><td>10</td><td>第 1、2、11 篇</td></tr><tr><td>Reference → Core Features</td><td>14</td><td>第 3 篇</td></tr><tr><td>Reference → Web</td><td>8</td><td>第 4、5 篇</td></tr><tr><td>Reference → Data</td><td>3</td><td>第 6 篇</td></tr><tr><td>Reference → I/O</td><td>11</td><td>第 7 篇</td></tr><tr><td>Reference → Messaging</td><td>8</td><td>第 8 篇</td></tr><tr><td>Reference → Testing</td><td>7</td><td>第 9 篇</td></tr><tr><td>Reference → Actuator</td><td>13</td><td>第 10 篇</td></tr><tr><td>Reference → Packaging</td><td>13</td><td>第 11 篇</td></tr><tr><td>How-to Guides</td><td>25</td><td>各篇的&quot;常见问题&quot;小节</td></tr><tr><td>Specification / Appendix</td><td>40+</td><td>附录与速查</td></tr><tr><td>API Documentation</td><td>66531</td><td>不搬运，改为在各篇给出&quot;该查哪个类&quot;的索引</td></tr></tbody></table><p>教程没有漏掉官方任何一章，边缘技术（gRPC、Hazelcast、Pulsar 等）以&quot;要点 + 最小可运行示例&quot;的方式收录。</p><h2 id="适合谁读" tabindex="-1">适合谁读 <a class="header-anchor" href="#适合谁读" aria-label="Permalink to &quot;适合谁读&quot;">​</a></h2><ul><li>学过 Java 基础、会用 Maven，但没完整做过一个 Spring Boot 项目的学生；</li><li>从 Spring Boot 2.x / 3.x 上来，需要知道 4.x 有哪些破坏性变更的开发者；</li><li>需要一份能直接给课堂用的实训材料，要求代码可运行、结果可复现的老师。</li></ul><p>前置要求：Java 17 及以上、Maven、能跑 Docker（第 9 篇的 Testcontainers 与第 11 篇的容器化会用到）。环境准备见<a href="/backend-engineering-course/ch00/03.html">第 0 篇的环境准备</a>。</p><h2 id="怎么用这个站点" tabindex="-1">怎么用这个站点 <a class="header-anchor" href="#怎么用这个站点" aria-label="Permalink to &quot;怎么用这个站点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>想做的事</th><th>怎么做</th></tr></thead><tbody><tr><td>按顺序学</td><td>左侧边栏按&quot;阶段 → 篇 → 小节&quot;组织，从<a href="/backend-engineering-course/ch00/">第 0 篇</a>往下走</td></tr><tr><td>查某个知识点</td><td>右上角的搜索框支持全文检索，中文可用</td></tr><tr><td>对照官方原文</td><td>每篇导学页顶部有&quot;本篇对应官方章节&quot;，链接可直接点开</td></tr><tr><td>换个角度看代码</td><td>右上角可切换深色模式；正文里的代码块带语言标注，可直接复制</td></tr><tr><td>打印或存成 PDF</td><td>打印样式会去掉导航与侧边栏，只留正文</td></tr></tbody></table><h2 id="关于版本" tabindex="-1">关于版本 <a class="header-anchor" href="#关于版本" aria-label="Permalink to &quot;关于版本&quot;">​</a></h2><p>官方文档站 <code>docs.spring.io/spring-boot/</code> 默认指向当前 GA 版本，即 4.1.x。教程里所有&quot;官方原文&quot;的引用都来自该版本，链接可以直接点开核对。</p><div class="warning custom-block"><p class="custom-block-title">版本会变</p><p>版本号属于易变信息，通常半年内会有小版本更新。若在几个月后阅读，先到官方的 <a href="https://docs.spring.io/spring-boot/system-requirements.html" target="_blank" rel="noreferrer">System Requirements</a> 确认当前要求，再对照本地工程的启动日志。正文里的写法（注解、API、配置项）比版本号稳定得多。</p></div>',17)])])}const g=e(o,[["render",n]]);export{p as __pageData,g as default};
